// Graph as adjacency list (undirected)
class Graph {
  #adj = new Map();

  addVertex(v)        { if (!this.#adj.has(v)) this.#adj.set(v, []); }
  addEdge(u, v)       { this.#adj.get(u)?.push(v); this.#adj.get(v)?.push(u); } // undirected
  neighbours(v)       { return this.#adj.get(v) ?? []; }

  // BFS — O(V + E), shortest hop count
  bfs(start) {
    const visited = new Set([start]);
    const queue   = [start];
    const order   = [];
    const dist    = new Map([[start, 0]]);
    while (queue.length) {
      const v = queue.shift();               // O(n) — use linked-list queue in prod
      order.push(v);
      for (const nb of this.neighbours(v)) {
        if (!visited.has(nb)) {
          visited.add(nb);
          dist.set(nb, dist.get(v) + 1);
          queue.push(nb);
        }
      }
    }
    return { order, dist };
  }

  // DFS — O(V + E), iterative
  dfs(start) {
    const visited = new Set();
    const stack   = [start];
    const order   = [];
    while (stack.length) {
      const v = stack.pop();
      if (visited.has(v)) continue;
      visited.add(v);
      order.push(v);
      for (const nb of this.neighbours(v)) {
        if (!visited.has(nb)) stack.push(nb);
      }
    }
    return order;
  }

  // Cycle detection via DFS on directed graph
  hasCycle(vertices) {
    const WHITE = 0, GRAY = 1, BLACK = 2;
    const color = new Map(vertices.map(v => [v, WHITE]));
    const dfs = v => {
      color.set(v, GRAY);
      for (const nb of (this.#adj.get(v) ?? [])) {
        if (color.get(nb) === GRAY) return true;  // back edge = cycle
        if (color.get(nb) === WHITE && dfs(nb)) return true;
      }
      color.set(v, BLACK);
      return false;
    };
    return vertices.some(v => color.get(v) === WHITE && dfs(v));
  }
}

const g = new Graph();
['A','B','C','D','E'].forEach(v => g.addVertex(v));
g.addEdge('A','B'); g.addEdge('A','C');
g.addEdge('B','D'); g.addEdge('C','D'); g.addEdge('C','E');

const { order: bfsOrder, dist } = g.bfs('A');
console.log('BFS:', bfsOrder);            // ['A','B','C','D','E']
console.log('dist C:', dist.get('C'));    // 1
console.log('dist D:', dist.get('D'));    // 2
console.log('DFS:', g.dfs('A'));          // ['A','C','E','D','B']

// Adjacency list vs adjacency matrix
//
// Graph: 4 vertices (0,1,2,3), edges: 0-1, 0-2, 1-3

// Adjacency list — O(V+E) space
const adjList = {
  0: [1, 2],
  1: [0, 3],
  2: [0],
  3: [1]
};

// Adjacency matrix — O(V²) space
const adjMatrix = [
//  0  1  2  3
  [ 0, 1, 1, 0 ],  // from 0
  [ 1, 0, 0, 1 ],  // from 1
  [ 1, 0, 0, 0 ],  // from 2
  [ 0, 1, 0, 0 ]   // from 3
];

// Operation comparison:
// Has edge (u,v)?     | adjList: O(degree(u)) | matrix: O(1)
// List neighbours(v)? | adjList: O(degree(v)) | matrix: O(V)
// Space               | O(V+E)                | O(V²)
// Best for            | sparse graphs          | dense graphs

// Topological sort (Kahn's BFS algorithm for DAGs)
function topoSort(graph, vertices) {
  const inDegree = new Map(vertices.map(v => [v, 0]));
  for (const v of vertices)
    for (const nb of (graph[v] ?? [])) inDegree.set(nb, inDegree.get(nb) + 1);
  const queue  = vertices.filter(v => inDegree.get(v) === 0);
  const result = [];
  while (queue.length) {
    const v = queue.shift();
    result.push(v);
    for (const nb of (graph[v] ?? [])) {
      inDegree.set(nb, inDegree.get(nb) - 1);
      if (inDegree.get(nb) === 0) queue.push(nb);
    }
  }
  return result.length === vertices.length ? result : []; // empty = cycle detected
}
